changeSet.sql:
CREATE TABLE wishlist_items ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
buyer_user_id uuid NOT NULL REFERENCES users (id), listing_type varchar(16) NOT NULL, listing_id uuid NOT NULL, name_at_save varchar(255) NOT NULL, price_at_save numeric(19, 4), currency varchar(3), saved_at timestamp(6) with time zone NOT NULL,
CONSTRAINT chk_wishlist_items_listing_type CHECK (listing_type IN ('PRIMARY')), CONSTRAINT chk_wishlist_items_price_currency CHECK ((price_at_save IS NULL) = (currency IS NULL)) ); CREATE UNIQUE INDEX uq_wishlist_items_buyer_listing ON wishlist_items (buyer_user_id, listing_type, listing_id); CREATE INDEX idx_wishlist_items_buyer ON wishlist_items (buyer_user_id, saved_at DESC);
COMMENT ON TABLE wishlist_items IS 'A buyer''s saved listings, at most 200 each (enforced by the service under a per-buyer lock). Buyer-owned: not RLS-policied, reached by buyer_user_id only. Hard-deleted on removal: a preference, not history. See AGENTS.md, "The buyer''s wishlist".'; COMMENT ON COLUMN wishlist_items.price_at_save IS 'The listing''s from-price when saved, from marketplace_listings, never from the request. Only marks a change since; never shown as the price.';
